cd /home/runner/work/monica-conv && python3 - <<'PY'
import subprocess, re, yaml, collections
files=[l for l in subprocess.run(["git","ls-tree","-r","--name-only","origin/main"],capture_output=True,text=True).stdout.split("\n") if re.match(r"^S\d+/E\d+\.md$",l)]
files.sort()
problems=[]
for f in files:
    txt=subprocess.run(["git","show","origin/main:"+f],capture_output=True,text=True).stdout
    if not txt.startswith("---\n"):
        problems.append((f,"no frontmatter")); continue
    end=txt.index("\n---\n",4)
    fm=yaml.safe_load(txt[4:end])
    body=txt[end+5:]
    for k in ("title","summary","season","episode","status"):
        if k not in fm: problems.append((f,"missing "+k))
    t=fm.get("title","")
    if not (t.startswith('The One With ') and t.endswith('"')==False and t.count('"')==0): pass
    if not t.startswith("The One With "): problems.append((f,"title style: "+t))
    s=fm.get("summary","")
    w=len(s.split())
    if not (18<=w<=38): problems.append((f,f"summary words {w}"))
    first=body.strip().split("\n")[0].strip()
    if first!=s.strip(): problems.append((f,"intro paragraph != summary"))
    m=re.match(r"S(\d+)/E(\d+)\.md",f)
    if int(fm.get("season",0))!=int(m.group(1)) or int(fm.get("episode",0))!=int(m.group(2)):
        problems.append((f,"season/episode mismatch"))
    # entries count
    n=len(re.findall(r"^Source: friend/",body,re.M))
    if re.search(r"status: ongoing",txt) and n>60: problems.append((f,f"ongoing with {n} entries"))
print("checked",len(files),"files")
print("problems:",len(problems))
for p in problems[:40]: print("  ",p)
